    keyConceptsDetailed: [{name: 'Pramāṇa', explanation: 'A means, source, process, or episode of reliable cognition according to context.', whyItMatters: 'It cannot be reduced without argument to modern knowledge or justified true belief.'}, {name: 'Perception', explanation: 'Nonconceptual presentation of a unique particular.', whyItMatters: 'It distinguishes causal contact from naming and classification.'}, {name: 'Inference', explanation: 'Conceptual cognition produced through a sign or reason that does not deviate from the target.', whyItMatters: 'It supports private understanding and public correction.'}, {name: 'Triple criterion', explanation: 'A reason must occur in the subject, relevant similar cases, and no relevant dissimilar case.', whyItMatters: 'It disciplines inferential support without reducing it to syntax alone.'}, {name: 'Apoha', explanation: 'Generality explained through exclusion rather than separately real universals.', whyItMatters: 'It connects language, nominalism, cognition, and action while remaining contested.'}, {name: 'Causal efficacy', explanation: 'The power of a particular to produce effects and fulfill an expected function.', whyItMatters: 'It links reality, perceptual confirmation, and practical reliability.'}],
